+import { AppError, type PublicUser } from "@arcade/shared";
+import type { EngineCatalog, MatchRepository, ObservabilityPort } from "../domain/ports";
+
+export function createAdminUseCases(deps: {
+  matches: MatchRepository;
+  engines: EngineCatalog;
+  obs: ObservabilityPort;
+}) {
+  return {
+    async insights(user: PublicUser) {
+      if (user.role !== "admin") throw new AppError("Forbidden", 403, "forbidden");
+
+      const [popularity, recent, leaderboard] = await Promise.all([
+        deps.matches.popularity(),
+        deps.matches.recentMatches(30),
+        deps.matches.globalScoreboard(10),
+      ]);
+
+      const catalogue = deps.engines.list().map((e) => ({
+        id: e.id,
+        name: e.name,
+      }));
+
+      const enriched = catalogue.map((g) => {
+        const p = popularity.find((x) => x.gameId === g.id);
+        return {
+          gameId: g.id,
+          name: g.name,
+          plays: p?.plays ?? 0,
+          humanWins: p?.humanWins ?? 0,
+          botWins: p?.botWins ?? 0,
+          draws: p?.draws ?? 0,
+          plays24h: p?.plays24h ?? 0,
+        };
+      }).sort((a, b) => b.plays - a.plays);
+
+      void deps.obs.log("info", "admin.insights", { admin: user.username });
+      void deps.obs.span({
+        name: "admin.insights",
+        attributes: { "user.name": user.username },
+      });
+
+      return {
+        popularity: enriched,
+        recent,
+        leaderboard,
+        totals: {
+          plays: enriched.reduce((s, g) => s + g.plays, 0),
+          plays24h: enriched.reduce((s, g) => s + g.plays24h, 0),
+        },
+      };
+    },
+  };
+}
+
+export type AdminUseCases = ReturnType<typeof createAdminUseCases>;
diff --git a/apps/api/src/application/auth.ts b/apps/api/src/application/auth.ts
new file mode 100644
index 0000000..e712b57
--- /dev/null
+++ b/apps/api/src/application/auth.ts
@@ -0,0 +1,69 @@
+import { AppError, type PublicUser } from "@arcade/shared";
+import type { ObservabilityPort, SessionRepository, UserRepository } from "../domain/ports";
+import { makePasswordHash, makeToken, verifyPassword } from "../infrastructure/auth/password";
+
+const SESSION_DAYS = 30;
+
+export function createAuthUseCases(deps: {
+  users: UserRepository;
+  sessions: SessionRepository;
+  obs: ObservabilityPort;
+}) {
+  return {
+    async register(username: string, password: string) {
+      const name = username.trim().toLowerCase();
+      if (name.length < 3 || name.length > 32) {
+        throw new AppError("Username must be 3–32 characters");
+      }
+      if (name === "admin") throw new AppError("Username reserved");
+      if (password.length < 4) throw new AppError("Password must be at least 4 characters");
+
+      try {
+        const user = await deps.users.create(name, makePasswordHash(password), "user");
+        void deps.obs.log("info", "auth.register", { user: user.username });
+        void deps.obs.metric("arcade_events", 1, { event: "register" });
+        return this.login(name, password);
+      } catch (e: unknown) {
+        if (String(e).includes("unique") || String(e).includes("duplicate")) {
+          throw new AppError("Username already taken");
+        }
+        throw e;
+      }
+    },
+
+    async login(username: string, password: string) {
+      const name = username.trim().toLowerCase();
+      const user = await deps.users.findByUsername(name);
+      if (!user || !verifyPassword(password, user.passwordHash)) {
+        throw new AppError("Invalid credentials", 401, "unauthorized");
+      }
+      const token = makeToken();
+      const expires = new Date(Date.now() + SESSION_DAYS * 86400_000);
+      await deps.sessions.create(token, user.id, expires);
+      const publicUser: PublicUser = {
+        id: user.id,
+        username: user.username,
+        role: user.role,
+      };
+      void deps.obs.log("info", "auth.login", { user: publicUser.username, role: publicUser.role });
+      void deps.obs.metric("arcade_events", 1, { event: "login" });
+      void deps.obs.span({
+        name: "auth.login",
+        attributes: { "user.name": publicUser.username, "user.role": publicUser.role },
+      });
+      return { user: publicUser, token, maxAge: SESSION_DAYS * 86400 };
+    },
+
+    async logout(token: string | undefined) {
+      if (token) await deps.sessions.delete(token);
+      void deps.obs.log("info", "auth.logout", {});
+    },
+
+    async me(token: string | undefined) {
+      if (!token) return null;
+      return deps.sessions.findUserByToken(token);
+    },
+  };
+}
+
+export type AuthUseCases = ReturnType<typeof createAuthUseCases>;
diff --git a/apps/api/src/application/games.ts b/apps/api/src/application/games.ts
new file mode 100644
index 0000000..9c0d407
--- /dev/null
+++ b/apps/api/src/application/games.ts
@@ -0,0 +1,156 @@
+import { AppError, type MatchDto, type MatchResult, type PublicUser } from "@arcade/shared";
+import type {
+  EngineCatalog,
+  MatchRepository,
+  ObservabilityPort,
+} from "../domain/ports";
+
+function toDto(m: {
+  id: number;
+  gameId: string;
+  state: unknown;
+  status: string;
+  winner: MatchResult;
+}): MatchDto {
+  return {
+    id: m.id,
+    gameId: m.gameId,
+    state: m.state,
+    status: m.status as MatchDto["status"],
+    winner: m.winner,
+  };
+}
+
+export function createGameUseCases(deps: {
+  matches: MatchRepository;
+  engines: EngineCatalog;
+  obs: ObservabilityPort;
+}) {
+  return {
+    listGames() {
+      return deps.engines.list().map((e) => ({
+        id: e.id,
+        name: e.name,
+        description: e.description,
+      }));
+    },
+
+    async getOrCreateMatch(user: PublicUser, gameId: string, traceId?: string) {
+      const engine = (() => {
+        try {
+          return deps.engines.require(gameId);
+        } catch {
+          throw new AppError("Unknown game", 404, "not_found");
+        }
+      })();
+
+      let match = await deps.matches.findActive(user.id, gameId);
+      if (!match) {
+        match = await deps.matches.create(user.id, gameId, engine.newState());
+        await deps.matches.addEvent({
+          matchId: match.id,
+          actor: "system",
+          move: { event: "start" },
+          traceId,
+        });
+        void deps.obs.log("info", "match.start", {
+          game_id: gameId,
+          match_id: match.id,
+          user: user.username,
+        });
+        void deps.obs.metric("arcade_matches_total", 1, { game: gameId, result: "started" });
+        void deps.obs.metric("arcade_game_popularity", 1, { game: gameId });
+        void deps.obs.span({
+          name: "match.start",
+          traceId,
+          attributes: { "game.id": gameId, "match.id": match.id, "user.name": user.username },
+        });
+      }
+      return toDto(match);
+    },
+
+    async newMatch(user: PublicUser, gameId: string, traceId?: string) {
+      deps.engines.require(gameId);
+      await deps.matches.abandonActive(user.id, gameId);
+      return this.getOrCreateMatch(user, gameId, traceId);
+    },
+
+    async applyMove(
+      user: PublicUser,
+      gameId: string,
+      move: unknown,
+      traceId?: string,
+    ): Promise<MatchDto> {
+      const engine = (() => {
+        try {
+          return deps.engines.require(gameId);
+        } catch {
+          throw new AppError("Unknown game", 404, "not_found");
+        }
+      })();
+
+      const match = await deps.matches.findActive(user.id, gameId);
+      if (!match) throw new AppError("No active match", 404, "not_found");
+
+      const human = engine.applyHumanMove(match.state, move);
+      if (human.illegal) throw new AppError("Illegal move");
+
+      let state = human.state;
+      await deps.matches.addEvent({
+        matchId: match.id,
+        actor: "human",
+        move,
+        traceId,
+      });
+      void deps.obs.metric("arcade_moves_total", 1, { game: gameId, actor: "human" });
+
+      let status = engine.status(state);
+      if (status === "playing") {
+        state = engine.applyBotMove(state);
+        await deps.matches.addEvent({
+          matchId: match.id,
+          actor: "bot",
+          move: { auto: true },
+          traceId,
+        });
+        void deps.obs.metric("arcade_moves_total", 1, { game: gameId, actor: "bot" });
+        status = engine.status(state);
+      }
+
+      match.state = state;
+      if (status === "playing") {
+        match.status = "playing";
+        match.winner = null;
+      } else {
+        match.status = "finished";
+        match.winner = status;
+        void deps.obs.log("info", "match.end", {
+          game_id: gameId,
+          match_id: match.id,
+          result: status,
+          user: user.username,
+        });
+        void deps.obs.metric("arcade_matches_total", 1, { game: gameId, result: status });
+        void deps.obs.span({
+          name: "match.end",
+          traceId,
+          attributes: {
+            "game.id": gameId,
+            "match.id": match.id,
+            result: status,
+          },
+        });
+      }
+
+      const updated = await deps.matches.update(match);
+      void deps.obs.span({
+        name: "match.move",
+        traceId,
+        attributes: { "game.id": gameId, "match.id": match.id },
+      });
+      return toDto(updated);
+    },
+  };
+}
+
+export type GameUseCases = ReturnType<typeof createGameUseCases>;
