--- /dev/null
+++ b/apps/web/src/styles.css
@@ -0,0 +1,221 @@
+:root {
+  --ink: #14201b;
+  --paper: #eef6f0;
+  --mint: #7dffa2;
+  --teal: #1f6f5b;
+  --sand: #f3e7c9;
+  --danger: #c44b3c;
+  --line: rgba(20, 32, 27, 0.12);
+  --shadow: 0 24px 60px rgba(20, 32, 27, 0.12);
+  font-family: "Space Grotesk", sans-serif;
+  color: var(--ink);
+  background: var(--paper);
+}
+
+* { box-sizing: border-box; }
+
+html, body, #root { margin: 0; min-height: 100%; }
+
+body {
+  min-height: 100vh;
+  background:
+    radial-gradient(circle at 12% 18%, rgba(125, 255, 162, 0.45), transparent 34%),
+    radial-gradient(circle at 88% 10%, rgba(243, 231, 201, 0.7), transparent 28%),
+    linear-gradient(160deg, #f7fbf8 0%, #e4f0e8 48%, #d7ebe1 100%);
+}
+
+button, input { font: inherit; }
+
+.app {
+  width: min(1100px, calc(100% - 2rem));
+  margin: 0 auto;
+  padding: 2rem 0 3rem;
+  animation: rise 0.55s ease both;
+}
+
+@keyframes rise {
+  from { opacity: 0; transform: translateY(12px); }
+  to { opacity: 1; transform: none; }
+}
+
+.brand {
+  font-size: clamp(2.4rem, 7vw, 4rem);
+  font-weight: 700;
+  letter-spacing: -0.06em;
+  line-height: 0.95;
+  margin: 0;
+}
+.brand span { color: var(--teal); }
+
+.tagline {
+  margin: 0.75rem 0 0;
+  max-width: 34rem;
+  opacity: 0.78;
+}
+
+.nav {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 0.5rem;
+  margin-top: 1.25rem;
+}
+
+.nav button.active {
+  background: var(--mint);
+  color: var(--ink);
+}
+
+.panel {
+  margin-top: 1.5rem;
+  padding: 1.35rem;
+  background: rgba(255, 255, 255, 0.62);
+  border: 1px solid var(--line);
+  backdrop-filter: blur(10px);
+  box-shadow: var(--shadow);
+}
+
+.auth-form, .stack { display: grid; gap: 0.85rem; max-width: 380px; }
+.auth-form label { display: grid; gap: 0.35rem; font-weight: 600; font-size: 0.9rem; }
+.auth-form input {
+  border: 1px solid var(--line);
+  background: #fff;
+  padding: 0.75rem 0.85rem;
+  outline: none;
+}
+.auth-form input:focus {
+  border-color: var(--teal);
+  box-shadow: 0 0 0 3px rgba(31, 111, 91, 0.15);
+}
+
+.row { display: flex; gap: 0.65rem; flex-wrap: wrap; align-items: center; }
+
+.btn {
+  border: 0;
+  cursor: pointer;
+  padding: 0.7rem 1.05rem;
+  background: var(--ink);
+  color: #fff;
+  font-weight: 600;
+  transition: transform 0.15s ease;
+}
+.btn:hover { transform: translateY(-1px); }
+.btn.secondary { background: transparent; color: var(--ink); border: 1px solid var(--line); }
+.btn.mint { background: var(--mint); color: var(--ink); }
+.btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }
+
+.error { color: var(--danger); margin: 0; font-size: 0.9rem; }
+.hint { margin: 0; opacity: 0.65; font-size: 0.92rem; }
+.status { font-weight: 600; font-size: 1.05rem; }
+.status.win { color: var(--teal); }
+.status.lose { color: var(--danger); }
+
+.grid-cards {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
+  gap: 1rem;
+  margin-top: 1rem;
+}
+
+.game-card {
+  text-align: left;
+  border: 1px solid var(--line);
+  background: #fff;
+  padding: 1.1rem;
+  cursor: pointer;
+  transition: transform 0.12s ease, background 0.15s ease;
+}
+.game-card:hover { transform: translateY(-2px); background: var(--sand); }
+.game-card h3 { margin: 0 0 0.4rem; font-size: 1.2rem; }
+.game-card p { margin: 0; opacity: 0.72; font-size: 0.92rem; }
+.badge {
+  display: inline-block;
+  margin-top: 0.75rem;
+  font-family: "IBM Plex Mono", monospace;
+  font-size: 0.75rem;
+  opacity: 0.7;
+}
+
+.stats {
+  display: flex;
+  gap: 1rem;
+  flex-wrap: wrap;
+  font-family: "IBM Plex Mono", monospace;
+  font-size: 0.85rem;
+}
+.stats strong { display: block; font-size: 1.25rem; }
+
+.board {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(72px, 100px));
+  gap: 0.5rem;
+}
+.board.c4 {
+  grid-template-columns: repeat(7, minmax(36px, 48px));
+  gap: 0.35rem;
+}
+.cell {
+  aspect-ratio: 1;
+  border: 1px solid var(--line);
+  background: #fff;
+  font-family: "IBM Plex Mono", monospace;
+  font-size: clamp(1.4rem, 4vw, 2.2rem);
+  font-weight: 500;
+  cursor: pointer;
+}
+.cell:hover:not(:disabled) { background: var(--sand); }
+.cell:disabled { cursor: default; }
+.cell.x { color: var(--teal); }
+.cell.o { color: var(--ink); }
+.cell.p1 { background: var(--mint); }
+.cell.p2 { background: var(--ink); }
+.cell.empty { background: #fff; }
+
+.c4-cols {
+  display: grid;
+  grid-template-columns: repeat(7, minmax(36px, 48px));
+  gap: 0.35rem;
+  margin-bottom: 0.4rem;
+}
+
+.rps-choices { display: flex; gap: 0.65rem; flex-wrap: wrap; }
+.rps-pick {
+  min-width: 110px;
+  padding: 1rem;
+  border: 1px solid var(--line);
+  background: #fff;
+  cursor: pointer;
+  font-weight: 600;
+}
+.rps-pick:hover:not(:disabled) { background: var(--sand); }
+
+table.data {
+  width: 100%;
+  border-collapse: collapse;
+  font-size: 0.92rem;
+}
+table.data th, table.data td {
+  text-align: left;
+  padding: 0.55rem 0.4rem;
+  border-bottom: 1px solid var(--line);
+}
+table.data th { font-size: 0.8rem; opacity: 0.7; }
+
+.bars { display: grid; gap: 0.65rem; margin-top: 1rem; }
+.bar-row { display: grid; grid-template-columns: 120px 1fr 48px; gap: 0.5rem; align-items: center; }
+.bar-track { height: 10px; background: rgba(20,32,27,0.08); overflow: hidden; }
+.bar-fill { height: 100%; background: var(--teal); }
+
+.topbar {
+  display: flex;
+  justify-content: space-between;
+  gap: 1rem;
+  flex-wrap: wrap;
+  align-items: flex-end;
+}
+
+@media (max-width: 640px) {
+  .app { padding-top: 1.25rem; }
+  .panel { padding: 1rem; }
+  .board { width: 100%; grid-template-columns: repeat(3, 1fr); }
+  .board.c4, .c4-cols { width: 100%; grid-template-columns: repeat(7, 1fr); }
+}
